#define glDeleteSync bionic_glDeleteSync
#define glDeleteTextures bionic_glDeleteTextures
#define glDiscardFramebufferEXT bionic_glDiscardFramebufferEXT
#define glDrawArrays bionic_glDrawArrays
#define glDrawArraysIndirect bionic_glDrawArraysIndirect
#define glDrawArraysInstanced bionic_glDrawArraysInstanced
#define glDrawArraysInstancedEXT bionic_glDrawArraysInstancedEXT
#define glDrawElements bionic_glDrawElements
#define glDrawElementsBaseVertex bionic_glDrawElementsBaseVertex
#define glDrawElementsBaseVertexEXT bionic_glDrawElementsBaseVertexEXT
#define glDrawElementsBaseVertexOES bionic_glDrawElementsBaseVertexOES
#define glDrawElementsIndirect bionic_glDrawElementsIndirect
#define glDrawElementsInstanced bionic_glDrawElementsInstanced
#define glDrawElementsInstancedBaseVertex bionic_glDrawElementsInstancedBaseVertex
#define glDrawElementsInstancedBaseVertexEXT bionic_glDrawElementsInstancedBaseVertexEXT
#define glDrawElementsInstancedBaseVertexOES bionic_glDrawElementsInstancedBaseVertexOES
#define glDrawElementsInstancedEXT bionic_glDrawElementsInstancedEXT
#define glDrawRangeElements bionic_glDrawRangeElements
#define glDrawRangeElementsBaseVertex bionic_glDrawRangeElementsBaseVertex
#define glDrawRangeElementsBaseVertexEXT bionic_glDrawRangeElementsBaseVertexEXT
#define glDrawRangeElementsBaseVertexOES bionic_glDrawRangeElementsBaseVertexOES
#define glEGLImageTargetRenderbufferStorageOES bionic_glEGLImageTargetRenderbufferStorageOES
#define glEGLImageTargetTexture2DOES bionic_glEGLImageTargetTexture2DOES
#define glFenceSync bionic_glFenceSync
#define glFinish bionic_glFinish
#define glFlush bionic_glFlush
#define glFramebufferRenderbuffer bionic_glFramebufferRenderbuffer
#define glFramebufferTexture bionic_glFramebufferTexture
#define glFramebufferTexture2D bionic_glFramebufferTexture2D
#define glFramebufferTextureEXT bionic_glFramebufferTextureEXT
#define glFramebufferTextureLayer bionic_glFramebufferTextureLayer
#define glFramebufferTextureOES bionic_glFramebufferTextureOES
#define glGenerateMipmap bionic_glGenerateMipmap
#define glGetSynciv bionic_glGetSynciv
#define glGetObjectPtrLabel bionic_glGetObjectPtrLabel
#define glGetObjectPtrLabelKHR bionic_glGetObjectPtrLabelKHR
#define glInvalidateFramebuffer bionic_glInvalidateFramebuffer
